// CLX Lead Research v2 — Parse Claude Response
// Reads Claude API response via $input.item.json and the current lead
// via $('Split In Batches').first().json (stable first-item accessor).

const response = $input.item.json;
const lead = $('Split In Batches').first().json;

const rawText = (response && response.content && response.content[0] && response.content[0].text) || '';

// What the provider actually returned. n8n's error shape varies, so every
// plausible carrier is checked and the result is truncated -- this is
// triage information, and it must never contain a key.
const providerError = response._transport_ok ? null : (response._transport_reason || response._transport);
const httpHint = response._http_status || null;
const diagnostic = providerError
  ? (response._transport + ': ' + String(providerError).slice(0, 300))
  : (rawText ? null : 'EMPTY_PROVIDER_RESPONSE');

let research;
try {
  const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  research = JSON.parse(cleaned);
} catch (e) {
  // Keep whatever text came back for triage, but do not pretend it is
  // research. If rawText is empty the summary is empty, and an empty
  // summary must not be dressed up as a completed research pass.
  research = {
    research_summary: rawText.substring(0, 500),
    likely_business_need: null,
    research_angle: 'General outreach',
    _research_error: 'parse_error: ' + String(e && e.message).slice(0, 200)
  };
}

const now = new Date().toISOString();

// THE PIPELINE-ORDERING BUG, at its source.
//
// lead_status was set to 'Researched' unconditionally. When the model
// returned nothing, research_summary was '' -- and update_lead applies
// NULLIF(value,'') so the column stayed NULL while the status said
// Researched. clx-lead-scoring-v2 fetches lead_status=eq.Researched,
// so 1,373 leads with no research reached the scorer, which had nothing
// to reason about and wrote a zero.
//
// The status now reflects what actually happened.
const summary = (research.research_summary || '').trim();
// A model that says it cannot analyse the lead has not researched it. The
// sentence is a well-formed answer to the question asked, which is exactly
// why it slipped through: non-empty text passed the length check and became
// a completed research pass. Same rule as scoring and signals -- an absence
// of findings is not a finding.
const INSUFFICIENT = /^\s*insufficient_data\s*$|unable to analyz|unable to determine|insufficient (lead )?data|not enough (information|data)|no (company|lead) (name|data|information)/i;
const insufficient = INSUFFICIENT.test(summary);
const researchOk = summary.length > 0 && !research._research_error && !insufficient;

if (research._research_error) {
  console.log('RESEARCH PARSE FAILURE:', JSON.stringify({ lead_id: lead.id, error: research._research_error }));
}

return {
  json: {
    id: lead.id,
    research_summary: researchOk ? summary : '',
    likely_business_need: research.likely_business_need || '',
    research_angle: research.research_angle || '',
    lead_status: researchOk ? 'Researched' : (insufficient ? 'Research Insufficient Data' : 'Research Failed'),
    researched_at: researchOk ? now : null,
    _research_error: research._research_error || null,
    _diagnostic: diagnostic || research._research_error || (insufficient ? ('insufficient_data: ' + summary.slice(0, 200)) : null),
    _http_hint: httpHint || null,
    _model_replied: Boolean(rawText),
    // Bumped whenever this workflow changes. Three deploys have now
    // reported success while live behaviour said otherwise; this makes
    // the running build self-identifying rather than inferred.
    _wf_build: 'r4-codenode-classifier',
    _transport: response._transport || null,
    updated_at: now
  }
};

// CLX Lead Research v2 — Skip-Apollo gate (Task 2)
// If the lead's email is on a personal domain (gmail/yahoo/etc.)
// AND there's no linkedin_url / apollo_org_id / company_size signal,
// this is most likely a residential B2C lead and Apollo would burn a
// credit for zero enrichment value. Skip-Apollo flag short-circuits
// the Execute Workflow call.
//
// Router's Decide Segment will later reclassify and persist
// lead_segment, but that happens downstream. This gate is purely a
// cost-saving guard for B2C leads that arrive through B2C discovery
// sources (google_maps, facebook_local).

const lead = $input.item.json;
const PERSONAL_DOMAINS = /@(gmail|yahoo|hotmail|outlook|icloud|live|aol|proton|protonmail|me)\./i;

const hasBusinessSignals = !!(lead.linkedin_url || lead.apollo_org_id || Number(lead.company_size) > 1);
const personalEmail = lead.email && PERSONAL_DOMAINS.test(String(lead.email));

const skipApollo = personalEmail && !hasBusinessSignals;

return { json: { ...lead, _skip_apollo: skipApollo } };

// CLX Lead Research v2 — Prep Update Lead
// Builds the RPC body from $input.item.json (the Parse output for this lead).

const item = $input.item.json;

const body = {
  p_lead_id: item.id,
  p_fields: {
    research_summary: item.research_summary,
    likely_business_need: item.likely_business_need,
    research_angle: item.research_angle,
    // Whatever Parse Claude Response concluded. This line used to hardcode
    // 'Researched', which silently discarded that node's entire purpose:
    // a lead whose research failed was written as Researched with an empty
    // summary, update_lead's NULLIF turned the summary into NULL, and the
    // status claimed a research pass that never happened. The honesty fix
    // was applied to the node that COMPUTES the status and undone by the
    // node that WRITES it.
    lead_status: item.lead_status || 'Research Failed',
    researched_at: item.researched_at
  }
};

console.log('PREP UPDATE:', JSON.stringify({ lead_id: item.id, status: body.p_fields.lead_status }));

return { json: { ...item, rpc_body: JSON.stringify(body),
  _transport: item._transport || null, _wf_build: item._wf_build || null,
  _needs_error_log: !!item._research_error || !(item.research_summary || '').trim() } };

// Build the Anthropic request from the ORIGINAL lead.
//
// This lives in a Code node rather than an inline expression because the
// prompt is multi-line: as an expression it required escaped newlines
// inside a JavaScript string literal, and a single unescaped one silently
// broke the whole request. Same shape the decision engine uses.

const lead = $('Split In Batches').first().json;

const val = function (v) {
  const s = (v === null || v === undefined) ? '' : String(v).trim();
  return s || 'not provided';
};

const emailDomain = String(lead.email || '').split('@')[1] || '';

const details = [
  'Company: ' + val(lead.company),
  'Industry: ' + val(lead.industry),
  'Job Title: ' + val(lead.job_title),
  'Contact: ' + val(lead.full_name),
  'City: ' + val(lead.city),
  'Website: ' + val(lead.website),
  'LinkedIn: ' + val(lead.linkedin_url),
  'Email domain: ' + val(emailDomain),
  'Source: ' + val(lead.source),
  'Vertical: ' + val(lead.vertical || lead.product_type),
  'Company size: ' + val(lead.company_size)
].join('\n');

const prompt = [
  'You are a B2B sales intelligence analyst for the Crystallux Sales Engine.',
  '',
  'Analyze this lead and return ONLY a raw JSON object. No markdown, no code',
  'blocks, no explanation.',
  '',
  'Lead Details:',
  details,
  '',
  'Return a JSON object with exactly these three string fields:',
  '- research_summary: 2-3 sentences on what the attributes above tell us about',
  '  this business and the market it operates in',
  '- likely_business_need: the single most likely business challenge it faces',
  '- research_angle: the specific outreach angle to use when contacting this lead',
  '',
  'Ground every statement in the attributes given -- industry, location, size,',
  'web presence. Reasoning from those to a market position is the job and is',
  'expected. What you must NOT do is invent specifics you were not given:',
  'no funding, hiring, awards, expansion, named clients, revenue, recent events',
  'or compliments. If you did not receive it, do not assert it.',
  '',
  'Only if the company name AND industry are both missing, set research_summary',
  'to exactly INSUFFICIENT_DATA.'
].join('\n');

// How much the model actually had to work with. Recorded so an
// INSUFFICIENT_DATA answer can be told apart from a provider failure
// without re-reading the prompt.
const supplied = ['company', 'industry', 'job_title', 'city', 'website', 'full_name']
  .filter(function (f) { return lead[f] && String(lead[f]).trim(); });

return { json: {
  lead_id: lead.id,
  _fields_supplied: supplied,
  _field_count: supplied.length,
  research_payload: {
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 1024,
    messages: [{ role: 'user', content: prompt }]
  }
} };

// Name the transport outcome before anything tries to parse it.
//
// A 401, a timeout and an empty body all used to arrive at Parse Claude
// Response as "no content", so a provider outage looked identical to a
// model that said nothing. The parser should interpret model output, not
// discover that the call never happened.

const resp = $input.item.json || {};
const built = $('Build Research Prompt').item.json;

// n8n reports failures in several shapes depending on where they occurred.
const err = resp.error || resp.__error || null;
const status = resp.statusCode || resp.status ||
               (err && (err.statusCode || err.status)) || null;

let text = '';
try { text = (resp.content && resp.content[0] && resp.content[0].text) || ''; } catch (e) {}

const RETRYABLE = [408, 425, 429, 500, 502, 503, 504];

let transport, reason, retryable = false;

if (err) {
  const msg = typeof err === 'string' ? err : JSON.stringify(err);
  const isTimeout = /timeout|etimedout|econnreset|socket hang up|enotfound/i.test(msg);
  const isAuth = /401|invalid[_ ]api[_ ]key|authentication|unauthorized|permission/i.test(msg);
  transport = 'PROVIDER_ERROR';
  reason = (status ? ('HTTP ' + status + ': ') : '') + msg.slice(0, 300);
  retryable = isTimeout || (status && RETRYABLE.indexOf(Number(status)) >= 0);
  if (isAuth) { transport = 'PROVIDER_AUTH_FAILED'; retryable = false; }
} else if (status && Number(status) >= 300) {
  transport = 'PROVIDER_ERROR';
  reason = 'HTTP ' + status;
  retryable = RETRYABLE.indexOf(Number(status)) >= 0;
} else if (!text) {
  transport = 'EMPTY_PROVIDER_RESPONSE';
  reason = 'HTTP 2xx with no message content';
} else {
  transport = 'OK';
  reason = null;
}

return { json: Object.assign({}, resp, {
  _transport: transport,
  _transport_ok: transport === 'OK',
  _transport_reason: reason,
  _http_status: status || (transport === 'OK' ? 200 : null),
  _retryable: retryable,
  _fields_supplied: built._fields_supplied,
  _field_count: built._field_count
}) };
